             color.g / lightSaturation,
             color.b / lightSaturation,
             1.0f};

        state.lights.changed = true;
        minGLStateChange();
        glLightModelfv(GL_LIGHT_MODEL_AMBIENT, c);
        state.lights.ambient = color;
    }
