             settings.width, "ok",
             settings.height, "ok",
             (settings.fullScreen ? "Fullscreen" : "Windowed"), "ok"
             );
    }



	inPrimitive        = false;
	inIndexedPrimitive = false;

    if (debugLog) debugLog->println("Done initializing RenderDevice.\n");

    _initialized = true;

    if (alphaBits != 0) {
        enableAlphaWrite();
    }

    setCaption("3D");

    _window->m_renderDevice = this;

    return true;
}


