void RenderDevice::setStencilClearValue(int s) {
    debugAssert(! inPrimitive);
    minStateChange();
    if (state.stencil.stencilClear != s) {
        minGLStateChange();
        glClearStencil(s);
        state.stencil.stencilClear = s;
    }
}


void RenderDevice::setDepthClearValue(double d) {
    minStateChange();
    debugAssert(! inPrimitive);
