    for (int i = 0; i < width * height; ++i) {
        out.byte()[i * 3 + 0] = byte()[i * channels + 0];
        out.byte()[i * 3 + 1] = byte()[i * channels + 1];
        out.byte()[i * 3 + 2] = byte()[i * channels + 2];
