#include "G3D/g3dmath.h"
#include <stdio.h>

namespace Ogre
{
    extern int fontTextureCounter;

    class VRbxFont
    {
        int subWidth[128];
        int charWidth;
        int charHeight;
        int baseline;
        TexturePtr texture;

    public:
        VRbxFont(const String& filename, G3D::BinaryInput& input);
    };

