const Pass* RbxSceneManager::deriveShadowReceiverPass(const Pass* pass)  {

    if (isShadowTechniqueTextureBased())
    {
		Pass* retPass = mShadowTextureCustomReceiverPass ? 
			mShadowTextureCustomReceiverPass : mShadowReceiverPass;

